CREATE TABLE migrations (id INTEGER PRIMARY KEY AUTO_INCREMENT, name VARCHAR(100) NOT NULL UNIQUE, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE users (id INTEGER PRIMARY KEY AUTO_INCREMENT, name VARCHAR(60) NOT NULL, email VARCHAR(190) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, role VARCHAR(16) NOT NULL DEFAULT 'player', is_guest INTEGER NOT NULL DEFAULT 0, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE cards (id INTEGER PRIMARY KEY AUTO_INCREMENT, slug VARCHAR(60) NOT NULL UNIQUE, name VARCHAR(80) NOT NULL, description TEXT NOT NULL, type VARCHAR(30) NOT NULL DEFAULT 'criatura', element VARCHAR(20) NOT NULL, rarity VARCHAR(20) NOT NULL, cost INTEGER NOT NULL, image_url VARCHAR(255) NOT NULL, model_url VARCHAR(255) DEFAULT NULL, marker_url VARCHAR(255) NOT NULL, color VARCHAR(7) NOT NULL, active INTEGER NOT NULL DEFAULT 1, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE monsters (id INTEGER PRIMARY KEY AUTO_INCREMENT, card_id INTEGER NOT NULL UNIQUE, attack INTEGER NOT NULL, defense INTEGER NOT NULL, hp INTEGER NOT NULL, archetype VARCHAR(30) NOT NULL, animations JSON NOT NULL, FOREIGN KEY (card_id) REFERENCES cards(id) ON DELETE CASCADE);
CREATE TABLE card_abilities (id INTEGER PRIMARY KEY AUTO_INCREMENT, card_id INTEGER NOT NULL, code VARCHAR(30) NOT NULL, name VARCHAR(80) NOT NULL, description TEXT NOT NULL, FOREIGN KEY (card_id) REFERENCES cards(id) ON DELETE CASCADE);
CREATE TABLE user_cards (user_id INTEGER NOT NULL, card_id INTEGER NOT NULL, quantity INTEGER NOT NULL DEFAULT 3, PRIMARY KEY (user_id,card_id), FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE, FOREIGN KEY (card_id) REFERENCES cards(id));
CREATE TABLE decks (id INTEGER PRIMARY KEY AUTO_INCREMENT, user_id INTEGER NOT NULL, name VARCHAR(60) NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE INDEX decks_owner ON decks(user_id);
CREATE TABLE deck_cards (deck_id INTEGER NOT NULL, card_id INTEGER NOT NULL, quantity INTEGER NOT NULL, PRIMARY KEY (deck_id,card_id), FOREIGN KEY (deck_id) REFERENCES decks(id) ON DELETE CASCADE, FOREIGN KEY (card_id) REFERENCES cards(id));
CREATE TABLE battles (id INTEGER PRIMARY KEY AUTO_INCREMENT, user_id INTEGER NOT NULL, status VARCHAR(20) NOT NULL DEFAULT 'active', state_json JSON NOT NULL, version INTEGER NOT NULL DEFAULT 1, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (user_id) REFERENCES users(id));
CREATE INDEX battles_owner_status ON battles(user_id,status);
CREATE TABLE battle_players (id INTEGER PRIMARY KEY AUTO_INCREMENT, battle_id INTEGER NOT NULL, user_id INTEGER DEFAULT NULL, side VARCHAR(10) NOT NULL, hp INTEGER NOT NULL DEFAULT 4000, UNIQUE(battle_id,side), FOREIGN KEY (battle_id) REFERENCES battles(id) ON DELETE CASCADE, FOREIGN KEY (user_id) REFERENCES users(id));
CREATE TABLE battle_turns (id INTEGER PRIMARY KEY AUTO_INCREMENT, battle_id INTEGER NOT NULL, turn_number INTEGER NOT NULL, side VARCHAR(10) NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, UNIQUE(battle_id,turn_number), FOREIGN KEY (battle_id) REFERENCES battles(id) ON DELETE CASCADE);
CREATE TABLE battle_actions (id INTEGER PRIMARY KEY AUTO_INCREMENT, battle_id INTEGER NOT NULL, turn_number INTEGER NOT NULL, event_type VARCHAR(30) NOT NULL, actor VARCHAR(10) NOT NULL, payload JSON NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (battle_id) REFERENCES battles(id) ON DELETE CASCADE);
CREATE INDEX actions_battle ON battle_actions(battle_id,id);
CREATE TABLE battle_monsters (id INTEGER PRIMARY KEY AUTO_INCREMENT, battle_id INTEGER NOT NULL, card_id INTEGER NOT NULL, unit_key INTEGER NOT NULL, side VARCHAR(10) NOT NULL, hp INTEGER NOT NULL, state_json JSON NOT NULL, UNIQUE(battle_id,unit_key), FOREIGN KEY (battle_id) REFERENCES battles(id) ON DELETE CASCADE, FOREIGN KEY (card_id) REFERENCES cards(id));
CREATE TABLE player_statistics (user_id INTEGER PRIMARY KEY, battles INTEGER NOT NULL DEFAULT 0, wins INTEGER NOT NULL DEFAULT 0, losses INTEGER NOT NULL DEFAULT 0, damage_dealt INTEGER NOT NULL DEFAULT 0, experience INTEGER NOT NULL DEFAULT 0, FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE);
